    /**
     * Tests getting all PerformanceMetrics.
     *
     * @return    Collection
     */
    public List<PerformanceMetric> testGetAll() throws Throwable {
    LOGGER.info( "PerformanceMetricTest:testGetAll() - Retrieving Collection of PerformanceMetrics:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all PerformanceMetric : " );
    List<PerformanceMetric> collection  = null;

    try {
        // call the static get method on the PerformanceMetricService
        collection = service.getAllPerformanceMetric();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            PerformanceMetric currEntity  = null;
            Iterator<PerformanceMetric> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getPerformanceMetricId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

